// Phase 1: the hero scroll animation.
// Retouched video frames of the Qur'an opening, drawn to a canvas by scroll position.
// Spec: WEBSITE-BUILD.md sections 2 and 3; the settings the user chose are under section 7.

(() => {
  const clamp = (v) => Math.min(1, Math.max(0, v));

  // Frames --------------------------------------------------------------------

  const SKIP = [39, 40]; // identical to f038, a hold in the source video
  const urls = [];
  for (let i = 0; i <= 88; i++) {
    if (!SKIP.includes(i)) urls.push(`assets/hero/frames/f${String(i).padStart(3, '0')}.png`);
  }
  const LAST = urls.length - 1; // 87 frames, indices 0..86

  // Geometry, in pixels of the 1280x720 frames ----------------------------------

  const SRC_W = 1280;
  const SRC_H = 720;
  const BOOK_LEFT = 255;   // left edge of the book; it never moves in the footage
  const BOOK_H = 580;      // y 70-650, centred on the frame's middle
  const SPINE = 640;       // right edge until the cover passes upright
  const OPEN_RIGHT = 1037; // right edge fully open
  const FEATHER_X = 180;   // how far the frame's rectangle fades into the stage
  const FEATHER_Y = 40;

  // Timeline, as a share of the hero's scroll ------------------------------------

  const OPEN_START = 0.1;
  const OPEN_END = 0.6;

  // Smoothing ---------------------------------------------------------------------

  // A mouse wheel scrolls in steps, so the book glides toward the scroll position instead of
  // jumping to it. Each value is roughly how many seconds it takes to close two thirds of the gap.
  // TRYOUT: the user is comparing these with the buttons at the bottom of the page.
  const GLIDES = { 'As now': 0, 'Quick glide': 0.07, 'Soft glide': 0.14, 'Slow glide': 0.28 };
  let glide = GLIDES['Soft glide'];
  let blend = false; // cross-fade the two nearest frames when the book is between them

  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
  const hero = document.querySelector('.hero');
  const stage = hero.querySelector('.stage');
  const canvas = stage.querySelector('canvas');
  const ctx = canvas.getContext('2d');

  const frames = []; // decoded images by index, filled in as they arrive
  const rights = []; // measured right edge of the book in each frame
  const started = new Set();

  let pos = null;   // frame position on screen; fractional while gliding or between frames
  let drawn = null; // position last drawn
  let last = 0;     // time of the previous glide step, 0 when the book is at rest
  let dirty = true;
  let queued = false;
  let visible = true;

  // Loading -----------------------------------------------------------------------

  function load(i) {
    if (started.has(i)) return;
    started.add(i);
    const img = new Image();
    img.src = urls[i];
    img.decode().then(
      () => {
        frames[i] = img;
        rights[i] = measureRight(img);
        dirty = true;
        schedule();
      },
      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
    );
  }

  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
  function loadAll() {
    load(0);
    load(LAST);
    for (const step of [8, 4, 2, 1]) {
      for (let i = 0; i <= LAST; i += step) load(i);
    }
  }

  // Once the cover passes upright its cream lining faces the camera, so the book's right
  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
  const probe = document.createElement('canvas');
  probe.width = SRC_W;
  probe.height = 1;
  const probeCtx = probe.getContext('2d', { willReadFrequently: true });

  function measureRight(img) {
    try {
      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
      for (let x = SRC_W - 1; x > SPINE; x--) {
        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
      }
      return SPINE;
    } catch {
      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
    }
  }

  // Averaged over nearby frames so the centring glides instead of stepping.
  function rightEdge(i) {
    let sum = 0;
    let n = 0;
    for (let j = Math.max(0, i - 3); j <= Math.min(LAST, i + 3); j++) {
      if (rights[j] != null) {
        sum += rights[j];
        n++;
      }
    }
    return n ? sum / n : SPINE + ((OPEN_RIGHT - SPINE) * i) / LAST;
  }

  // Drawing -----------------------------------------------------------------------

  // Draws the frame nearest a position, or with blending on, cross-fades the two either side of it.
  // Returns false while no frame has loaded yet.
  function draw(at) {
    const a = Math.floor(at);
    const b = Math.min(a + 1, LAST);
    const f = at - a;
    const fade = blend && f > 0 && !!frames[a] && !!frames[b];
    const base = fade ? a : nearestLoaded(Math.round(at));
    if (base < 0) return false;

    const width = canvas.clientWidth;
    const height = canvas.clientHeight;
    // One size for the whole opening: the open book always fits, and the 720p footage is
    // never stretched past its own size.
    const scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / (OPEN_RIGHT - BOOK_LEFT), 1);
    // The book is centred by choosing which part of the frame is drawn, never by moving the canvas.
    const centre = (BOOK_LEFT + rightEdge(a) + (rightEdge(b) - rightEdge(a)) * f) / 2;
    const w = SRC_W * scale;
    const h = SRC_H * scale;
    const x = width / 2 - centre * scale;
    const y = (height - h) / 2;

    ctx.globalCompositeOperation = 'source-over';
    ctx.clearRect(0, 0, width, height);
    ctx.drawImage(frames[base], x, y, w, h);
    if (fade) {
      ctx.globalAlpha = f;
      ctx.drawImage(frames[b], x, y, w, h);
      ctx.globalAlpha = 1;
    }

    // Fade the frame's rectangle out at its edges so it never shows against the stage.
    ctx.globalCompositeOperation = 'destination-in';
    ctx.fillStyle = feather(ctx.createLinearGradient(x, 0, x + w, 0), FEATHER_X / SRC_W);
    ctx.fillRect(x, y, w, h);
    ctx.fillStyle = feather(ctx.createLinearGradient(0, y, 0, y + h), FEATHER_Y / SRC_H);
    ctx.fillRect(x, y, w, h);
    ctx.globalCompositeOperation = 'source-over';
    return true;
  }

  function feather(gradient, edge) {
    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
    gradient.addColorStop(edge, '#000');
    gradient.addColorStop(1 - edge, '#000');
    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
    return gradient;
  }

  // Where the scroll says the book should be, in frames (fractional).
  function targetPos() {
    if (reduceMotion.matches) return LAST;
    const range = hero.offsetHeight - stage.offsetHeight;
    const p = range > 0 ? clamp(-hero.getBoundingClientRect().top / range) : 0;
    const t = clamp((p - OPEN_START) / (OPEN_END - OPEN_START));
    return t * t * (3 - 2 * t) * LAST; // smoothstep: eases into and out of the opening
  }

  function nearestLoaded(i) {
    for (let d = 0; d <= LAST; d++) {
      if (frames[i - d]) return i - d;
      if (frames[i + d]) return i + d;
    }
    return -1;
  }

  function schedule() {
    if (queued) return;
    queued = true;
    requestAnimationFrame(step);
  }

  // Each animation frame, moves the book part of the way toward the scroll position and keeps
  // going until it arrives. Uses elapsed time, so it feels the same on 60 Hz and 144 Hz screens.
  function step(now) {
    queued = false;
    if (!visible) {
      last = 0;
      return;
    }
    const target = targetPos();
    if (pos === null || !glide || reduceMotion.matches) {
      pos = target;
    } else {
      const dt = last ? Math.min(now - last, 50) / 1000 : 1 / 60;
      pos += (target - pos) * (1 - Math.exp(-dt / glide));
      if (Math.abs(target - pos) < 0.01) pos = target;
    }
    last = pos === target ? 0 : now;
    paint();
    if (pos !== target) schedule();
  }

  // Redraws only when the position, size, loaded frames or a setting have changed.
  function paint() {
    if (pos === null || (pos === drawn && !dirty)) return;
    if (draw(pos)) {
      drawn = pos;
      dirty = false;
    }
  }

  function resize() {
    const dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = Math.round(canvas.clientWidth * dpr);
    canvas.height = Math.round(canvas.clientHeight * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.imageSmoothingQuality = 'high';
    dirty = true;
    paint(); // draw now: resizing the canvas has just cleared it
  }

  // Reduced motion: no scrubbing, just the open book, and only its frame is loaded.
  function applyMotion() {
    document.documentElement.classList.toggle('still', reduceMotion.matches);
    if (reduceMotion.matches) load(LAST);
    else loadAll();
    dirty = true;
    schedule();
  }

  // TRYOUT --------------------------------------------------------------------------
  // Buttons for comparing the smoothing, shown only on this PC or a phone on the same wifi.
  // Once the user picks: set `glide` and `blend` above, then delete this block and .tryout in styles.css.

  if (/^(localhost|[\d.]+)$/.test(location.hostname)) {
    const bar = document.createElement('div');
    bar.className = 'tryout';
    const button = (label, pressed, onClick) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.textContent = label;
      b.setAttribute('aria-pressed', pressed);
      b.addEventListener('click', () => onClick(b));
      bar.append(b);
      return b;
    };
    const glideButtons = Object.entries(GLIDES).map(([label, seconds]) =>
      button(label, seconds === glide, (b) => {
        glide = seconds;
        for (const g of glideButtons) g.setAttribute('aria-pressed', g === b);
      }),
    );
    button(`Blend frames: ${blend ? 'on' : 'off'}`, blend, (b) => {
      blend = !blend;
      b.textContent = `Blend frames: ${blend ? 'on' : 'off'}`;
      b.setAttribute('aria-pressed', blend);
      dirty = true;
      schedule();
    });
    document.body.append(bar);
  }

  addEventListener('scroll', schedule, { passive: true });
  reduceMotion.addEventListener('change', applyMotion);
  new ResizeObserver(resize).observe(canvas);
  new IntersectionObserver(([entry]) => {
    visible = entry.isIntersecting;
    dirty = true;
    schedule();
  }).observe(hero);
  applyMotion();
})();

