/* Phase 1: hero scroll animation. Phase 2: theme tokens, fonts and the wordmark. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

/* Dark theme, from design-system/quran-landing/MASTER.md. The background is the footage's own #1F1A18
   rather than MASTER's #1C1917 (three shades apart), so the frame's edges disappear without a blend. */
:root {
  --color-background: #1F1A18;
  --color-foreground: #FAFAF9;
  --color-muted-foreground: #A8A29E;
  --color-accent: #D4AF37;
  --font-display: 'Bodoni Moda', Didot, Georgia, serif;
  --font-body: Jost, system-ui, sans-serif;
  color-scheme: dark;
}

html,
body {
  margin: 0;
  background: var(--color-background);
  color: var(--color-foreground);
  font-family: var(--font-body);
}

/* A tall section; the stage inside it stays pinned while it scrolls past. Its height sets
   how much scrolling the opening takes: slower on computers, where a mouse wheel moves in
   big steps, than on phones. */
.hero {
  position: relative;
  height: 550vh;
}

@media (max-width: 767px) {
  .hero {
    height: 400vh;
  }
}

.stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh; /* the book stays whole behind mobile browser bars */
  overflow: hidden;
}

.stage canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* The name, centred in the space above the closed book. --book-h is the book's height on screen,
   set by main.js, which also fades the name out as the cover starts to open. */
.wordmark {
  position: absolute;
  left: 0;
  right: 0;
  top: calc((50% - var(--book-h, 60svh) / 2) / 2);
  transform: translateY(-50%);
  padding: 0 1.5rem;
  text-align: center;
}

.wordmark h1 {
  margin: 0;
  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the name sits truly centred */
  font-family: var(--font-display);
  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.wordmark p {
  margin: 0.7em 0 0;
  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
  font-weight: 300;
  letter-spacing: 0.06em;
  color: var(--color-muted-foreground);
}

/* Reduced motion: no scrubbing, just the open book. */
.still .hero {
  height: auto;
}

/* TRYOUT: phase 2 options, set on <html> by main.js. Once the user picks, move the picks into :root
   and .wordmark above, then delete everything below. */
[data-font='garamond'] {
  --font-display: 'Cormorant Garamond', Garamond, Georgia, serif;
}

[data-font='cinzel'] {
  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
}

[data-gold='brass'] {
  --color-accent: #C9A962;
}

[data-gold='champagne'] {
  --color-accent: #E3CFA0;
}

[data-place='under'] .wordmark {
  top: auto;
  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
  transform: translateY(50%);
}

[data-line='off'] .wordmark p {
  display: none;
}

.tryout {
  position: fixed;
  left: 12px;
  bottom: 12px;
  max-width: calc(100vw - 24px);
  padding: 10px 12px;
  border: 1px solid #3F3A37;
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.7);
  font: 13px/1 system-ui, sans-serif;
  color: #e7e0d8;
}

.tryout summary {
  padding: 4px 0;
  cursor: pointer;
}

.tryout div {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.tryout span {
  min-width: 10em;
  color: #A8A29E;
}

.tryout button {
  padding: 10px 14px;
  border: 1px solid #5c5048;
  border-radius: 999px;
  background: transparent;
  color: #e7e0d8;
  font: inherit;
  cursor: pointer;
}

.tryout button[aria-pressed='true'] {
  border-color: #d4af37;
  color: #d4af37;
}

