// TRYOUT --------------------------------------------------------------------------
// Phase 2 options, shown only on this PC or a phone on the same wifi. Each choice sets a data
// attribute on <html> that styles.css reads. Once the user picks: move the picks into styles.css,
// then delete this block, the TRYOUT part of styles.css and the unused fonts in index.html.

if (/^(localhost|[\d.]+)$/.test(location.hostname)) {
  const OPTIONS = {
    font: ['Name font', { Bodoni: 'bodoni', Garamond: 'garamond', Cinzel: 'cinzel' }],
    gold: ['Gold', { 'Bright gold': 'bright', Brass: 'brass', Champagne: 'champagne' }],
    place: ['Name position', { 'Above the book': 'above', 'Under the book': 'under' }],
    line: ['Line under the name', { On: 'on', Off: 'off' }],
  };
  const panel = document.createElement('details');
  panel.className = 'tryout';
  panel.open = true;
  panel.innerHTML = '<summary>Options</summary>';
  for (const [key, [label, choices]] of Object.entries(OPTIONS)) {
    const row = document.createElement('div');
    const name = document.createElement('span');
    name.textContent = label;
    row.append(name);
    for (const [text, value] of Object.entries(choices)) {
      const b = document.createElement('button');
      b.type = 'button';
      b.textContent = text;
      b.addEventListener('click', () => {
        document.documentElement.dataset[key] = value;
        for (const other of row.querySelectorAll('button')) other.setAttribute('aria-pressed', other === b);
      });
      row.append(b);
    }
    row.querySelector('button').click(); // the first choice matches the defaults in styles.css
    panel.append(row);
  }
  document.body.append(panel);
}

