input.content:
// Copies aayat exactly, in Uthmani script, from the Quran.com API into site/aayat.json, so no verse is
// ever typed by hand. The text is saved unmodified, exactly as Quran.com sends it.
//
//   node fetch-aayat.js 96:1-5 73:4 54:17        one group per argument; a range stays together

const fs = require('fs');
const path = require('path');

async function verse(key) {
  const res = await fetch(`https://api.quran.com/api/v4/quran/verses/uthmani?verse_key=${key}`);
  if (!res.ok) throw new Error(`Quran.com answered ${res.status} for ${key}`);
  const found = (await res.json()).verses?.[0];
  if (found?.verse_key !== key || !found.text_uthmani) throw new Error(`No text came back for ${key}`);
  return found.text_uthmani;
}

(async () => {
  const refs = process.argv.slice(2);
  if (!refs.length) throw new Error('Name the aayat, e.g.  node fetch-aayat.js 96:1-5 73:4');

  const groups = [];
  for (const ref of refs) {
    const m = /^(\d{1,3}):(\d{1,3})(?:-(\d{1,3}))?$/.exec(ref);
    if (!m) throw new Error(`Not a reference like 73:4 or 96:1-5: ${ref}`);
    const surah = Number(m[1]);
    const from = Number(m[2]);
    const to = Number(m[3] ?? from);
    const aayat = [];
    for (let n = from; n <= to; n++) {
      const key = `${surah}:${n}`;
      aayat.push({ key, text: await verse(key) });
      console.log(`${key} ok`); // the Arabic itself is checked on the page; this window can't show it properly
    }
    groups.push({ ref, aayat });
  }

  const out = path.join(__dirname, 'site', 'aayat.json');
  const data = { source: 'Quran.com API v4, text_uthmani', fetched: new Date().toISOString().slice(0, 10), groups };
  fs.writeFileSync(out, `${JSON.stringify(data, null, 2)}\n`, 'utf8');
  console.log(`Saved ${out}`);
})().catch((err) => {
  console.error(err.message);
  process.exitCode = 1;
});

