    const right = el('div', 'page right');
    const arabic = el('p', 'arabic');
    arabic.lang = 'ar';
    arabic.dir = 'rtl';
    for (const { key, text } of verses) {
      const marker = el('span', 'marker', `۝${Number(key.split(':')[1]).toLocaleString('ar-u-nu-arab')}`);
