    const frame = still ? LAST : frameAt(pos);
    wordmark.style.opacity = still ? 1 : 1 - clamp(frame / NAME_GONE);
    showAayat(pos, still);
    painted = pos;
    if (frame !== drawn || dirty) {
      if (draw(frame)) {
        drawn = frame;
        dirty = false;
      }
    }
  }

