  // going until it arrives. Uses elapsed time, so it feels the same on 60 Hz and 144 Hz screens.
  function step(now) {
    queued = false;
    if (!visible) {
      last = 0;
      return;
    }
    const target = targetPos();
    if (pos === null || reduceMotion.matches) {
      pos = target;
    } else {
      const dt = last ? Math.min(now - last, 50) / 1000 : 1 / 60;
      pos += (target - pos) * (1 - Math.exp(-dt / GLIDE));
      if (Math.abs(target - pos) < 0.01) pos = target;
    }
    last = pos === target ? 0 : now;
    paint();
    if (pos !== target) schedule();
  }

  // Redraws only when the position, size, loaded frames or a setting have changed.
  function paint() {
    if (pos === null || (pos === drawn && !dirty)) return;
    // The name belongs to the closed book, so it fades as the cover lifts. Under reduced motion
    // the book is shown open, and the name stays.
    wordmark.style.opacity = reduceMotion.matches ? 1 : 1 - clamp(pos / NAME_GONE);
    if (draw(pos)) {
      drawn = pos;
      dirty = false;
    }
  }

  function resize() {
    const width = canvas.clientWidth;
    const height = canvas.clientHeight;
    const dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.imageSmoothingQuality = 'high';
    // One size for the whole opening: the open book always fits, and the 720p footage is
    // never stretched past its own size.
    scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / (OPEN_RIGHT - BOOK_LEFT), 1);
    stage.style.setProperty('--book-h', `${BOOK_H * scale}px`); // lets CSS place the name beside the book
    dirty = true;
    paint(); // draw now: resizing the canvas has just cleared it
    schedule(); // the hero's height follows the window, so the scroll position may now mean a different frame
  }

  // Reduced motion: no scrubbing, just the open book, and only its frame is loaded.
  function applyMotion() {
    document.documentElement.classList.toggle('still', reduceMotion.matches);
    if (reduceMotion.matches) load(LAST);
    else loadAll();
    dirty = true;
    schedule();
  }

  addEventListener('scroll', schedule, { passive: true });
  reduceMotion.addEventListener('change', applyMotion);
  new ResizeObserver(resize).observe(canvas);
  new IntersectionObserver(([entry]) => {
    visible = entry.isIntersecting;
    dirty = true;
    schedule();
  }).observe(hero);
  applyMotion();
})();

