toolUseResult.originalFile:
/* Phase 1: hero scroll animation. Phase 2: theme tokens, fonts and the headline. Phase 3: aayat on the pages. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

/* Dark theme, from design-system/quran-landing/MASTER.md. The background is the footage's own #1F1A18
   rather than MASTER's #1C1917 (three shades apart), so the frame's edges disappear without a blend.
   Cinzel for the headline and the bright gold were chosen by the user from on-page options. */
:root {
  --color-background: #1F1A18;
  --color-foreground: #FAFAF9;
  --color-muted-foreground: #A8A29E;
  --color-accent: #D4AF37;
  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
  --font-body: Jost, system-ui, sans-serif;
  --font-arabic: 'Amiri Quran', 'Scheherazade New', serif;
  color-scheme: dark;
}

html,
body {
  margin: 0;
  background: var(--color-background);
  color: var(--color-foreground);
  font-family: var(--font-body);
}

/* A tall section; the stage inside it stays pinned while it scrolls past. Its height is one screen
   plus the timeline in main.js (6.3 screens): the rest, the opening, then the aayat. Phones scroll
   two thirds as far, because a finger moves further per swipe than a mouse wheel per click. */
.hero {
  position: relative;
  height: 730vh;
}

.stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh; /* the book stays whole behind mobile browser bars */
  overflow: hidden;
}

.stage canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* The headline, centred in the space under the closed book. --book-h is the book's height on screen,
   set by main.js, which also fades it out as the cover starts to open. */
.wordmark {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
  transform: translateY(50%);
  padding: 0 1.5rem;
  text-align: center;
}

.wordmark h1 {
  margin: 0;
  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the text sits truly centred */
  font-family: var(--font-display);
  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.wordmark p {
  margin: 0.7em 0 0;
  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
  font-weight: 300;
  letter-spacing: 0.06em;
  color: var(--color-muted-foreground);
}

/* Aayat, laid over the open book's pages. The numbers are page positions in the 1280x720 footage:
   left page x 262-636, right page x 645-1020, both y 80-640. main.js sets --s (the book's scale) and
   --x0/--y0 (where the footage's corner sits once the book is open), and each group's opacity. */
.aayat {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.group {
  position: absolute;
  inset: 0;
  opacity: 0;
  mix-blend-mode: multiply; /* the ink sits in the paper, so the paper's shading shows through it */
}

.page {
  position: absolute;
  top: calc(var(--y0, 0px) + 80px * var(--s, 1));
  width: calc(375px * var(--s, 1));
  height: calc(560px * var(--s, 1));
  padding: calc(56px * var(--s, 1)) calc(40px * var(--s, 1));
  display: flex;
  flex-direction: column;
  justify-content: safe center;
  gap: 1.25em;
  overflow: hidden;
  text-align: center;
  color: #2B211B; /* dark ink, 14:1 on the cream page */
}

.page p {
  margin: 0;
}

.page.right {
  left: calc(var(--x0, 0px) + 645px * var(--s, 1));
  font-size: calc(30px * var(--s, 1));
}

.page.left {
  left: calc(var(--x0, 0px) + 262px * var(--s, 1));
  font-size: calc(16px * var(--s, 1));
}

.arabic {
  font-family: var(--font-arabic);
  line-height: 2.2; /* room for the marks above and below the letters */
}

.marker {
  color: #A16207; /* gold only for the small accents */
}

.surah {
  padding-left: 0.15em;
  font-family: var(--font-display);
  font-size: 1.2em;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #8A6A1F;
}

.meaning {
  display: none;
  font-weight: 400;
  line-height: 1.6;
  color: #3A302A;
}

.ref {
  font-size: 0.85em;
  letter-spacing: 0.08em;
  color: #6B5E55;
}

@media (max-width: 767px) {
  .hero {
    height: 520vh; /* one screen plus two thirds of 6.3 */
  }

  /* The pages are too small for a second block of text, so the left page's text sits under the book. */
  .group {
    mix-blend-mode: normal;
  }

  .page.left {
    left: 1.5rem;
    right: 1.5rem;
    width: auto;
    top: calc(var(--y0, 0px) + 650px * var(--s, 1) + 1rem);
    height: calc(var(--y0, 0px) + 70px * var(--s, 1) - 2rem);
    padding: 0;
    font-size: 0.875rem;
    color: var(--color-muted-foreground);
  }

  .page.left .surah {
    color: var(--color-accent);
  }

  .page.left .meaning,
  .page.left .ref {
    color: var(--color-muted-foreground);
  }
}

/* Reduced motion: no scrubbing, just the open book with the first group of aayat. */
.still .hero {
  height: auto;
}

/* TRYOUT: phase 3 options, set on <html> by main.js. Once the user picks, move the picks above and
   delete everything below. */
[data-arabic='scheherazade'] {
  --font-arabic: 'Scheherazade New', 'Amiri Quran', serif;
}

[data-left='meaning'] .meaning {
  display: block;
}

.tryout {
  position: fixed;
  left: 12px;
  bottom: 12px;
  max-width: calc(100vw - 24px);
  padding: 10px 12px;
  border: 1px solid #3F3A37;
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.7);
  font: 13px/1 system-ui, sans-serif;
  color: #e7e0d8;
}

.tryout summary {
  padding: 4px 0;
  cursor: pointer;
}

.tryout div {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.tryout span {
  min-width: 10em;
  color: #A8A29E;
}

.tryout button {
  padding: 10px 14px;
  border: 1px solid #5c5048;
  border-radius: 999px;
  background: transparent;
  color: #e7e0d8;
  font: inherit;
  cursor: pointer;
}

.tryout button[aria-pressed='true'] {
  border-color: #d4af37;
  color: #d4af37;
}

content.content:
1	// Phase 1: the hero scroll animation. Phase 2: the headline with the closed book. Phase 3: aayat on the open pages.
2	// Retouched video frames of the Qur'an opening, drawn to a canvas by scroll position.
3	// Spec: WEBSITE-BUILD.md sections 2 to 4; the settings the user chose are under section 7.
4	
5	(() => {
6	  const clamp = (v) => Math.min(1, Math.max(0, v));
7	  const smoothstep = (t) => t * t * (3 - 2 * t);
8	
9	  // Frames --------------------------------------------------------------------
10	
11	  const SKIP = [39, 40]; // identical to f038, a hold in the source video
12	  const urls = [];
13	  for (let i = 0; i <= 88; i++) {
14	    if (!SKIP.includes(i)) urls.push(`assets/hero/frames/f${String(i).padStart(3, '0')}.png`);
15	  }
16	  const LAST = urls.length - 1; // 87 frames, indices 0..86
17	
18	  // Geometry, in pixels of the 1280x720 frames ----------------------------------
19	
20	  const SRC_W = 1280;
21	  const SRC_H = 720;
22	  const BOOK_LEFT = 255;   // left edge of the book; it never moves in the footage
23	  const BOOK_H = 580;      // y 70-650, centred on the frame's middle
24	  const SPINE = 640;       // right edge until the cover passes upright
25	  const OPEN_RIGHT = 1037; // right edge fully open
26	  const FEATHER_X = 180;   // how far the frame's rectangle fades into the stage
27	  const FEATHER_Y = 40;
28	
29	  // Timeline, in screen heights of scrolling on a computer -----------------------
30	  // Phones scroll two thirds as far for everything (the hero is shorter there, in styles.css).
31	
32	  const REST = 0.45;  // closed book with the headline
33	  const OPEN = 2.25;  // the cover opens (the same scrolling as when the user signed off phase 1)
34	  const SETTLE = 0.4; // open, blank pages
35	  const GROUP = 0.8;  // each group of aayat fades in, holds, then fades out
36	  const TOTAL = REST + OPEN + SETTLE + GROUP * 4; // 6.3 for four groups; .hero is 100vh taller than this
37	  const NAME_GONE = 8; // the headline has faded out by this frame, early in the opening
38	
39	  // Smoothing ---------------------------------------------------------------------
40	
41	  // A mouse wheel scrolls in steps, so everything glides toward the scroll position instead of
42	  // jumping to it, and the book cross-fades between frames. The user chose this "slow glide" by eye.
43	  const GLIDE = 0.28; // roughly the seconds it takes to close two thirds of the gap
44	
45	  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
46	  const hero = document.querySelector('.hero');
47	  const stage = hero.querySelector('.stage');
48	  const canvas = stage.querySelector('canvas');
49	  const wordmark = stage.querySelector('.wordmark');
50	  const ctx = canvas.getContext('2d');
51	
52	  const frames = []; // decoded images by index, filled in as they arrive
53	  const rights = []; // measured right edge of the book in each frame
54	  const started = new Set();
55	  const groups = []; // one element per group of aayat, filled in when aayat.json arrives
56	
57	  let scale = 1;      // footage pixels to CSS pixels, set on resize
58	  let pos = null;     // scroll position shown, in screens; lags the real one while gliding
59	  let painted = null; // position last shown
60	  let drawn = null;   // frame last drawn; fractional between frames
61	  let last = 0;       // time of the previous glide step, 0 when at rest
62	  let dirty = true;
63	  let queued = false;
64	  let visible = true;
65	
66	  // Loading -----------------------------------------------------------------------
67	
68	  function load(i) {
69	    if (started.has(i)) return;
70	    started.add(i);
71	    const img = new Image();
72	    img.src = urls[i];
73	    img.decode().then(
74	      () => {
75	        frames[i] = img;
76	        rights[i] = measureRight(img);
77	        if (i >= LAST - 3) place(); // the open book's measured edge sets where the pages are
78	        dirty = true;
79	        schedule();
80	      },
81	      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
82	    );
83	  }
84	
85	  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
86	  function loadAll() {
87	    load(0);
88	    load(LAST);
89	    for (const step of [8, 4, 2, 1]) {
90	      for (let i = 0; i <= LAST; i += step) load(i);
91	    }
92	  }
93	
94	  // Once the cover passes upright its cream lining faces the camera, so the book's right
95	  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
96	  const probe = document.createElement('canvas');
97	  probe.width = SRC_W;
98	  probe.height = 1;
99	  const probeCtx = probe.getContext('2d', { willReadFrequently: true });
100	
101	  function measureRight(img) {
102	    try {
103	      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
104	      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
105	      for (let x = SRC_W - 1; x > SPINE; x--) {
106	        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
107	      }
108	      return SPINE;
109	    } catch {
110	      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
111	    }
112	  }
113	
114	  // Averaged over nearby frames so the centring glides instead of stepping.
115	  function rightEdge(i) {
116	    let sum = 0;
117	    let n = 0;
118	    for (let j = Math.max(0, i - 3); j <= Math.min(LAST, i + 3); j++) {
119	      if (rights[j] != null) {
120	        sum += rights[j];
121	        n++;
122	      }
123	    }
124	    return n ? sum / n : SPINE + ((OPEN_RIGHT - SPINE) * i) / LAST;
125	  }
126	
127	  // Aayat -------------------------------------------------------------------------
128	  // The exact text comes from aayat.json, written by fetch-aayat.js from Quran.com. Never typed by hand.
129	
130	  const aayat = document.createElement('div');
131	  aayat.className = 'aayat';
132	  stage.append(aayat);
133	
134	  function el(tag, className, text) {
135	    const node = document.createElement(tag);
136	    node.className = className;
137	    if (text) node.textContent = text;
138	    return node;
139	  }
140	
141	  // Arabic on the right page, the first page in a mushaf, each ayah closed by its numbered marker.
142	  // The left page carries the surah name, reference and English meaning.
143	  function renderGroup({ ref, surah, aayat: verses }) {
144	    const group = el('section', 'group');
145	    const right = el('div', 'page right');
146	    const arabic = el('p', 'arabic');
147	    arabic.lang = 'ar';
148	    arabic.dir = 'rtl';
149	    for (const { key, text } of verses) {
150	      const marker = el('span', 'marker', `۝${Number(key.split(':')[1]).toLocaleString('ar-u-nu-arab')}`);
151	      marker.setAttribute('aria-hidden', 'true');
152	      arabic.append(`${text} `, marker, ' ');
153	    }
154	    right.append(arabic);
155	    const left = el('div', 'page left');
156	    left.append(
157	      el('p', 'surah', surah),
158	      el('p', 'meaning', verses.map((v) => v.translation).join(' ')),
159	      el('p', 'ref', ref.replace('-', '–')),
160	    );
161	    group.append(right, left);
162	    return group;
163	  }
164	
165	  fetch('aayat.json')
166	    .then((res) => res.json())
167	    .then((data) => {
168	      for (const g of data.groups) groups.push(aayat.appendChild(renderGroup(g)));
169	      fit();
170	      dirty = true;
171	      schedule();
172	    })
173	    .catch(() => console.warn('No aayat yet: run fetch-aayat.js'));
174	
175	  // Where the open book's pages are: CSS lays the text over them from these.
176	  function place() {
177	    const open = (BOOK_LEFT + rightEdge(LAST)) / 2;
178	    stage.style.setProperty('--s', scale);
179	    stage.style.setProperty('--x0', `${canvas.clientWidth / 2 - open * scale}px`);
180	    stage.style.setProperty('--y0', `${(canvas.clientHeight - SRC_H * scale) / 2}px`);
181	    stage.style.setProperty('--book-h', `${BOOK_H * scale}px`);
182	  }
183	
184	  // Shrinks a page's text until it fits, for aayat longer than the page holds at its normal size.
185	  function fit() {
186	    for (const page of aayat.querySelectorAll('.page')) {
187	      page.style.fontSize = '';
188	      let size = parseFloat(getComputedStyle(page).fontSize);
189	      while (page.scrollHeight > page.clientHeight && size > 10) {
190	        size *= 0.94;
191	        page.style.fontSize = `${size}px`;
192	      }
193	    }
194	  }
195	
196	  // Each group fades in, holds, then fades out before the next begins, so two never overlap;
197	  // the last one stays. Under reduced motion the first group is simply shown.
198	  function showAayat(s, still) {
199	    groups.forEach((group, k) => {
200	      const local = (s - REST - OPEN - SETTLE) / GROUP - k;
201	      const fadeIn = smoothstep(clamp(local / 0.25));
202	      const fadeOut = k === groups.length - 1 ? 1 : 1 - smoothstep(clamp((local - 0.75) / 0.25));
203	      group.style.opacity = still ? Number(k === 0) : fadeIn * fadeOut;
204	    });
205	  }
206	
207	  // Drawing -----------------------------------------------------------------------
208	
209	  // Cross-fades the two frames either side of a position, or while they are still loading, draws
210	  // the nearest frame that has arrived. Returns false while no frame has loaded yet.
211	  function draw(at) {
212	    const a = Math.floor(at);
213	    const b = Math.min(a + 1, LAST);
214	    const f = at - a;
215	    const fade = f > 0 && !!frames[a] && !!frames[b];
216	    const base = fade ? a : nearestLoaded(Math.round(at));
217	    if (base < 0) return false;
218	
219	    const width = canvas.clientWidth;
220	    const height = canvas.clientHeight;
221	    // The book is centred by choosing which part of the frame is drawn, never by moving the canvas.
222	    const centre = (BOOK_LEFT + rightEdge(a) + (rightEdge(b) - rightEdge(a)) * f) / 2;
223	    const w = SRC_W * scale;
224	    const h = SRC_H * scale;
225	    const x = width / 2 - centre * scale;
226	    const y = (height - h) / 2;
227	
228	    ctx.globalCompositeOperation = 'source-over';
229	    ctx.clearRect(0, 0, width, height);
230	    ctx.drawImage(frames[base], x, y, w, h);
231	    if (fade) {
232	      ctx.globalAlpha = f;
233	      ctx.drawImage(frames[b], x, y, w, h);
234	      ctx.globalAlpha = 1;
235	    }
236	
237	    // Fade the frame's rectangle out at its edges so it never shows against the stage.
238	    ctx.globalCompositeOperation = 'destination-in';
239	    ctx.fillStyle = feather(ctx.createLinearGradient(x, 0, x + w, 0), FEATHER_X / SRC_W);
240	    ctx.fillRect(x, y, w, h);
241	    ctx.fillStyle = feather(ctx.createLinearGradient(0, y, 0, y + h), FEATHER_Y / SRC_H);
242	    ctx.fillRect(x, y, w, h);
243	    ctx.globalCompositeOperation = 'source-over';
244	    return true;
245	  }
246	
247	  function feather(gradient, edge) {
248	    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
249	    gradient.addColorStop(edge, '#000');
250	    gradient.addColorStop(1 - edge, '#000');
251	    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
252	    return gradient;
253	  }
254	
255	  // How far the hero has been scrolled, in computer screen heights (0 to TOTAL).
256	  function targetScroll() {
257	    const range = hero.offsetHeight - stage.offsetHeight;
258	    return range > 0 ? clamp(-hero.getBoundingClientRect().top / range) * TOTAL : 0;
259	  }
260	
261	  // The book's frame at a scroll position; smoothstep eases into and out of the opening.
262	  function frameAt(s) {
263	    return smoothstep(clamp((s - REST) / OPEN)) * LAST;
264	  }
265	
266	  function nearestLoaded(i) {
267	    for (let d = 0; d <= LAST; d++) {
268	      if (frames[i - d]) return i - d;
269	      if (frames[i + d]) return i + d;
270	    }
271	    return -1;
272	  }
273	
274	  function schedule() {
275	    if (queued) return;
276	    queued = true;
277	    requestAnimationFrame(step);
278	  }
279	
280	  // Each animation frame, moves part of the way toward the scroll position and keeps going until it
281	  // arrives. Uses elapsed time, so it feels the same on 60 Hz and 144 Hz screens.
282	  function step(now) {
283	    queued = false;
284	    if (!visible) {
285	      last = 0;
