1	/* Phase 1: hero scroll animation. Phase 2: theme tokens, fonts and the headline. Phase 3: aayat on the pages. */
2	
3	*,
4	*::before,
5	*::after {
6	  box-sizing: border-box;
7	}
8	
9	/* Dark theme, from design-system/quran-landing/MASTER.md. The background is the footage's own #1F1A18
10	   rather than MASTER's #1C1917 (three shades apart), so the frame's edges disappear without a blend.
11	   Cinzel for the headline and the bright gold were chosen by the user from on-page options. */
12	:root {
13	  --color-background: #1F1A18;
14	  --color-foreground: #FAFAF9;
15	  --color-muted-foreground: #A8A29E;
16	  --color-accent: #D4AF37;
17	  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
18	  --font-body: Jost, system-ui, sans-serif;
19	  --font-arabic: 'Amiri Quran', 'Scheherazade New', serif;
20	  color-scheme: dark;
21	}
22	
23	html,
24	body {
25	  margin: 0;
26	  background: var(--color-background);
27	  color: var(--color-foreground);
28	  font-family: var(--font-body);
29	}
30	
31	/* A tall section; the stage inside it stays pinned while it scrolls past. Its height is one screen
32	   plus the timeline in main.js (6.3 screens): the rest, the opening, then the aayat. Phones scroll
33	   two thirds as far, because a finger moves further per swipe than a mouse wheel per click. */
34	.hero {
35	  position: relative;
36	  height: 730vh;
37	}
38	
39	.stage {
40	  position: sticky;
41	  top: 0;
42	  height: 100vh;
43	  height: 100svh; /* the book stays whole behind mobile browser bars */
44	  overflow: hidden;
45	}
46	
47	.stage canvas {
48	  display: block;
49	  width: 100%;
50	  height: 100%;
51	}
52	
53	/* The headline, centred in the space under the closed book. --book-h is the book's height on screen,
54	   set by main.js, which also fades it out as the cover starts to open. */
55	.wordmark {
56	  position: absolute;
57	  left: 0;
58	  right: 0;
59	  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
60	  transform: translateY(50%);
61	  padding: 0 1.5rem;
62	  text-align: center;
63	}
64	
65	.wordmark h1 {
66	  margin: 0;
67	  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the text sits truly centred */
68	  font-family: var(--font-display);
69	  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
70	  font-weight: 500;
71	  line-height: 1.2;
72	  letter-spacing: 0.2em;
73	  text-transform: uppercase;
74	  color: var(--color-accent);
75	}
76	
77	.wordmark p {
78	  margin: 0.7em 0 0;
79	  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
80	  font-weight: 300;
81	  letter-spacing: 0.06em;
82	  color: var(--color-muted-foreground);
83	}
84	
85	/* Aayat, laid over the open book's pages. The numbers are page positions in the 1280x720 footage:
86	   left page x 262-636, right page x 645-1020, both y 80-640. main.js sets --s (the book's scale) and
87	   --x0/--y0 (where the footage's corner sits once the book is open), and each group's opacity. */
88	.aayat {
89	  position: absolute;
90	  inset: 0;
91	  pointer-events: none;
92	}
93	
94	.group {
95	  position: absolute;
96	  inset: 0;
97	  opacity: 0;
98	  mix-blend-mode: multiply; /* the ink sits in the paper, so the paper's shading shows through it */
99	}
100	
101	.page {
102	  position: absolute;
103	  top: calc(var(--y0, 0px) + 80px * var(--s, 1));
104	  width: calc(375px * var(--s, 1));
105	  height: calc(560px * var(--s, 1));
106	  padding: calc(56px * var(--s, 1)) calc(40px * var(--s, 1));
107	  display: flex;
108	  flex-direction: column;
109	  justify-content: safe center;
110	  gap: 1.25em;
111	  overflow: hidden;
112	  text-align: center;
113	  color: #2B211B; /* dark ink, 14:1 on the cream page */
114	}
115	
116	.page p {
117	  margin: 0;
118	}
119	
120	.page.right {
121	  left: calc(var(--x0, 0px) + 645px * var(--s, 1));
122	  font-size: calc(30px * var(--s, 1));
123	}
