// Each group fades in, holds, then fades out before the next begins, so two never overlap;
// the last one stays. Under reduced motion the first group is simply shown.
function showAayat(s, still) {
  groups.forEach((group, k) => {
    const local = (s - REST - OPEN - SETTLE) / GROUP - k;
    const fadeIn = smoothstep(clamp(local / 0.25));
    const fadeOut = k === groups.length - 1 ? 1 : 1 - smoothstep(clamp((local - 0.75) / 0.25));
    group.style.opacity = still ? Number(k === 0) : fadeIn * fadeOut;
  });
}

input.new_string:
// One group at a time, picked at random each time the pages come into view. It fades in once the
// book has settled open and stays; scrolling back up to blank pages lets the next pass pick again.
// Under reduced motion a random group is simply shown.
function showAayat(s, still) {
  const fade = still ? 1 : smoothstep(clamp((s - REST - OPEN - SETTLE) / FADE));
  if (fade === 0) current = -1;
  else if (current < 0 && groups.length) current = pick();
  groups.forEach((group, k) => {
    group.style.opacity = k === current ? fade : 0;
  });
}

// A random group, never the one shown last time.
function pick() {
  let k;
  do k = Math.floor(Math.random() * groups.length);
  while (groups.length > 1 && k === previous);
  return (previous = k);
}

